        sendHtml(response, 200, projectsPage(normalizeProjectFilter(url.searchParams.get('filter'))));
      } else if (request.method === 'POST' && pathname === '/projects') {
        const form = await readForm(request);
        const name = (form.get('name') ?? '').trim();
        if (!name) {
          sendHtml(response, 422, projectsPage(normalizeProjectFilter(form.get('filter')), 'Project name is required'));
          return;
        }
        insertProject.run(name);
        response.writeHead(303, { Location: '/' });
        response.end();
      } else if (projectRoute) {
        const id = Number(projectRoute[1]);
        const project = Number.isSafeInteger(id) ? findProject.get(id) : undefined;
        if (!project) {
          sendHtml(response, 404, page('Not found', '<h1>Project not found</h1><form action="/" method="get"><button>Projects</button></form>'));
          return;
        }
        const normalizeFilter = (value) => ['All', 'Open', 'Completed'].includes(value) ? value : 'All';
        if (request.method === 'GET' && pathname === `/projects/${id}`) {
          sendHtml(response, 200, projectPage(project, normalizeFilter(url.searchParams.get('filter'))));
        } else if (request.method === 'POST' && projectRoute[4] === 'rename') {
          const form = await readForm(request);
          const currentProject = findProject.get(id);
          const filter = normalizeFilter(form.get('filter'));
          if (currentProject.archived) {
            sendHtml(response, 403, projectPage(currentProject, filter, { renameError: 'Archived project is read-only' }));
            return;
          }
          const name = (form.get('name') ?? '').trim();
          if (!name) {
            sendHtml(response, 422, projectPage(currentProject, filter, { renameError: 'Project name is required' }));
            return;
          }
          renameProject.run(name, id);
          response.writeHead(303, { Location: `/projects/${id}?filter=${filter}` });
          response.end();
        } else if (request.method === 'POST' && projectRoute[4]) {
          updateArchive.run(projectRoute[4] === 'archive' ? 1 : 0, id);
          response.writeHead(303, { Location: projectRoute[4] === 'archive' ? '/' : '/?filter=Archived' });
          response.end();
        } else if (request.method === 'POST' && pathname.endsWith('/tasks')) {
          const form = await readForm(request);
          if (findProject.get(id).archived) {
            sendHtml(response, 403, projectPage(findProject.get(id), normalizeFilter(form.get('filter')), { taskError: 'Archived project is read-only' }));
            return;
          }
          const title = (form.get('title') ?? '').trim();
          const filter = normalizeFilter(form.get('filter'));
          if (!title) {
            sendHtml(response, 422, projectPage(project, filter, { taskError: 'Task title is required' }));
            return;
          }
          insertTask.run(id, title);
          response.writeHead(303, { Location: `/projects/${id}?filter=${filter}` });
          response.end();
        } else if (request.method === 'POST' && projectRoute[2]) {
          const form = await readForm(request);
          if (findProject.get(id).archived) {
            sendHtml(response, 403, projectPage(findProject.get(id), normalizeFilter(form.get('filter')), { taskError: 'Archived project is read-only' }));
            return;
          }
          const taskId = Number(projectRoute[2]);
          if (!Number.isSafeInteger(taskId) || !findTask.get(taskId, id)) {
            sendHtml(response, 404, page('Not found', '<h1>Task not found</h1>'));
            return;
          }
          if (projectRoute[3] === 'rename') {
            const title = (form.get('title') ?? '').trim();
            if (!title) {
              sendHtml(response, 422, projectPage(findProject.get(id), normalizeFilter(form.get('filter')), {
                taskRenameId: taskId, taskRenameError: 'Task title is required',
              }));
              return;
            }
            renameTask.run(title, taskId, id);
          } else if (projectRoute[3] === 'priority') {
            const priority = form.get('priority');
            if (!taskPriorities.includes(priority)) {
              sendHtml(response, 422, projectPage(findProject.get(id), normalizeFilter(form.get('filter')), {
                priorityError: 'Task priority must be Low, Normal, or High',
              }));
              return;
            }
            updateTaskPriority.run(priority, taskId, id);
          } else {
            updateTask.run(form.get('completed') === '1' ? 1 : 0, taskId, id);
          }
          response.writeHead(303, { Location: `/projects/${id}?filter=${normalizeFilter(form.get('filter'))}` });
          response.end();
        } else {
          sendHtml(response, 404, page('Not found', '<h1>Page not found</h1>'));
        }
      } else {
        sendHtml(response, 404, page('Not found', '<h1>Page not found</h1>'));
      }
    } catch (error) {
      if (!error.status) console.error(error);
      if (!response.headersSent) {
        sendHtml(response, error.status ?? 500, page('Error', '<h1>Unable to complete request</h1>'));
      } else {
        response.end();
      }
    }
  });
  server.on('close', () => database.close());
  return server;
}
# Workboard

Requires Node.js 22.22.1. There are no external dependencies.

```sh
npm start
```

The server binds to `0.0.0.0`, using `PORT` (default `8080`). SQLite data is
stored at `DB_PATH` (default `data/workboard.sqlite`). Parent directories are
created automatically. Reuse the same database path to preserve projects,
their tasks, task completion state, and archive state.
Project names, including later renames, persist at the same project URL.

```sh
PORT=8080 DB_PATH=/tmp/workboard.sqlite npm start
npm test
```

`GET /health` returns `{"status":"ok"}`. The application uses server-rendered
HTML forms; project names and task titles are trimmed on the server and escaped
for display. Each project has its own tasks, with All, Open, and Completed
filters. Changing a checkbox saves its completion state immediately; changing
the filter reloads the matching tasks in creation order. Browser JavaScript
submits these controls, with explicit submit buttons available without JavaScript.

The project list defaults to Active; select Archived to open or restore archived
projects. Archiving preserves all tasks and makes task creation and completion
read-only until restoration. Each project summary counts every task regardless
of task filters. Existing databases are migrated automatically, preserving IDs
and treating existing projects as active.

Active project pages provide a New project name field and Rename project button.
Renaming trims whitespace and preserves the project's identity, creation order,
tasks, and summary. Empty names are rejected. Archived projects disable renaming
